"""The Pi vectors of pi-ai's ``Type`` (test/parity/sdk-vectors/pi-ai/Type.json, generated by automation/gen/generate-sdk-vectors.mjs): what TypeBox 1.3.27's own constructors
and guards return, as the JSON text (so key order and number text are compared), the hidden members and the guards' booleans. Every case is run: the ones the host's type engine
answers need a host, so they run one by one through the host's own handler of the type.engine call in `go test ./test/extension-conformance -run TestTypeEngineVectorsThroughTheHost`
(run_engine_vectors.py), and here only their wire form is checked."""

from __future__ import annotations

import json
import re

import pytest

from pig_sdk import BigInt, Type
from type_vectors_support import all_cases, check_case, needs_host, non_engine_cases


def test_engine_served_cases_are_left_to_the_host():
    served = [case for case in all_cases() if needs_host(case)]
    assert len(served) > 300 and len(served) < len(all_cases())


@pytest.mark.parametrize("case", non_engine_cases(), ids=lambda case: case["name"])
def test_type_matches_pi(case):
    failure = check_case(case)
    assert failure is None, failure


def test_engine_arity_is_matched_by_count_as_pi_does():
    """TypeBox's Infer, Parameter, Script and Refine match their arguments by count (Arguments.Match): a missing or extra one is Pi's "Invalid Arguments", not Python's TypeError."""
    for call in (lambda: Type.infer(), lambda: Type.infer("T", Type.string(), Type.number()), lambda: Type.parameter(), lambda: Type.parameter("T", 1, 2, 3), lambda: Type.script()):
        with pytest.raises(ValueError, match="^Invalid Arguments$"):
            call()
    for call in (lambda: Type.refine(), lambda: Type.refine(Type.string()), lambda: Type.refine(Type.string(), lambda v: True, lambda v: "m", 1)):
        with pytest.raises(ValueError, match="^Invalid Arguments$"):
            call()


def test_type_omits_the_codec_family():
    """The evidence of divergence D198: the Codec family of Pi's Type is not served, so none of its members exists."""
    for name in ("codec", "decode", "encode", "decode_builder", "encode_builder", "is_codec"):
        assert not hasattr(Type, name), f"Type.{name} exists; D198 records that the Codec family is not served"


def _wire_cases() -> list[dict]:
    return [case for case in all_cases() if isinstance(case.get("result"), dict) and case["result"].get("wire") and "~refine" not in case["result"]["hidden"]]


@pytest.mark.parametrize("case", _wire_cases(), ids=lambda case: case["name"])
def test_engine_wire_round_trip(case):
    """The wire text TypeBox's own value has (the "wire" of the case) read through the SDK's decoder makes Pi's schema (the JSON text and the hidden members), and the SDK's encoder
    writes something that reads back as the same schema. The decoder and encoder are what every engine member goes through; the host's side is checked against the same vectors
    in internal/typebox/engine."""
    from pig_sdk.type_engine import _decode, _encode, _schema

    want = case["result"]
    value = _schema(_decode(json.loads(case["result"]["wire"]), []))
    if isinstance(value, list):
        return  # a schema made of a JavaScript array: its wire form is the plain list
    if "stringifyThrows" in want:
        with pytest.raises(TypeError, match=re.escape(want["stringifyThrows"])):
            value.to_json()  # the value holds a bigint
    else:
        assert value.to_json() == want["json"]
    for name, member in want["hidden"].items():
        if name != "~refine":  # functions have no JSON form: the vector records how many there are
            assert value.hidden.get(name) == member
    again = _schema(_decode(json.loads(json.dumps(_encode(value, []))), []))
    assert again == value and again.hidden == value.hidden


def test_a_schema_holds_a_bigint_and_only_writing_it_as_json_fails():
    """Pi's value holds a bigint (`Type.Literal(1n)`, a `Type.Script("1n")` result); `JSON.stringify` of it throws "Do not know how to serialize a BigInt"."""
    import pig_sdk

    literal = Type.literal(BigInt(10**30))
    assert Type.is_literal(literal) and literal["type"] == "bigint" and literal["const"] == BigInt(10**30)
    assert str(literal["const"]) == str(10**30) and literal["const"] != 10**30  # a Python int is a JavaScript number, not a bigint
    with pytest.raises(TypeError, match="^Do not know how to serialize a BigInt$"):
        literal.to_json()
    nested = Type.object({"a": literal})
    with pytest.raises(TypeError, match="^Do not know how to serialize a BigInt$"):
        nested.to_json()
    with pytest.raises(TypeError, match="^Do not know how to serialize a BigInt$"):
        pig_sdk.type_to_json(nested)
    with pytest.raises(TypeError):
        json.dumps(nested)
    ext = pig_sdk.Extension("bigint-probe")
    with pytest.raises(TypeError, match="^Do not know how to serialize a BigInt$"):
        ext.tool("t", "d", nested, lambda ctx, args: "ok")
    with pytest.raises(TypeError):
        Type.literal(1.5j)
    with pytest.raises(TypeError):
        BigInt(1.5)
    with pytest.raises(TypeError):
        BigInt(True)


def test_a_bigint_crosses_the_wire_as_pi_writes_it():
    from pig_sdk.type_engine import _decode, _encode

    wire = {"\x00": "n", "v": "-12345678901234567890"}
    assert _decode(wire, []) == BigInt(-12345678901234567890)
    assert _encode(BigInt(-12345678901234567890), []) == wire
